using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Codice.Mechanics;using Codice.Enemies;using Codice.Bosses;
public static class PopulateLab{public static string Run(){var path="Assets/00_Scenes/Maps/LaboratorioContenido.unity";var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);var room=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CombatTestRoom>(true)).First();room.enemyPrefabs=Resources.LoadAll<GameObject>("ExpeditionEnemies").Concat(Resources.LoadAll<GameObject>("WorldFour")).Where(g=>g.GetComponent<BasicEnemy>()||g.GetComponent<BossCharacter>()).OrderBy(g=>g.name).ToArray();EditorUtility.SetDirty(room);EditorSceneManager.SaveScene(scene);int count=room.enemyPrefabs.Length;EditorSceneManager.CloseScene(scene,true);return "Laboratory saved with "+count+" enemy/boss entries";}}

